import type {QuestionValues} from "./QuestionEditor";

type Draft={p:string;a:string;d:string[];e:string;short?:string[];exact?:boolean};
type Seed=QuestionValues&{seed_id:string};
const mc=(p:string,a:string,d:string[],e:string):Draft=>({p,a,d,e});
const sa=(p:string,a:string|string[],e:string,exact=false):Draft=>{const values=Array.isArray(a)?a:[a],accepted=new Set(values);for(const value of values){if(value.startsWith("$"))accepted.add(value.replace(/^\$\s*/,"").replaceAll(",",""));const unitless=value.replace(/\s*(?:cm|mm|km|m|°|m²|cm²)\s*$/i,"");if(unitless!==value)accepted.add(unitless)}return {p,a:values[0],d:[],e,short:[...accepted],exact}};
let choice=0;
function bank(code:string,items:Draft[]):Seed[]{
 if(items.length!==21)throw new Error(`${code}: expected 21 questions, got ${items.length}`);
 return items.map((q,i)=>{const seed_id=`10c50000-0000-4000-8000-${String(code.charCodeAt(0)).padStart(2,"0")}${String(code.charCodeAt(1)).padStart(2,"0")}${String(i+1).padStart(8,"0")}`;if(q.short)return {prompt:q.p,options:{kind:"short_answer",accepted:q.short,exact:q.exact},correct_index:0,explanation:q.e,seed_id};const slot=choice++%4,options=[...q.d];options.splice(slot,0,q.a);return {prompt:q.p,options,correct_index:slot,explanation:q.e,seed_id};});
}

